 applyOverrides();const ids=new Set(state.candidates.map(c=>c.id));state.saved=state.saved.filter(id=>ids.has(id));state.selected.clear();state.loading=false;persist();if(typeof profileResearchOnData==='function')profileResearchOnData();loadPublishedNetworking();
