const APP_STUDENT_STATUSES=new Set(['PhD student','PhD candidate',"Master's student",'Master’s student','Undergraduate student']);
const APP_ACADEMIC_STATUSES=new Set([...APP_STUDENT_STATUSES,'Postdoctoral researcher','Postdoc','Researcher','Faculty','Professor','Assistant professor','Associate professor','Industry researcher','Research engineer','Engineer','Graduated','Other academic role','Other']);
