function studentSourceUrl(value){try{const u=new URL(value),h=u.hostname.toLowerCase();return u.protocol==='https:'&&!u.username&&!u.password&&!u.port&&h.includes('.')&&!h.includes(':')&&!/^\d+(?:\.\d+){3}$/.test(h)&&!h.endsWith('.')&&!/\.(?:localhost|local|internal|lan|invalid|test|onion)$/.test(h)?u.href:null}catch{return null}}
function academicStatusProof(c,research,level='proposed'){
 const ids=new Set(c.paperIds||c.papers?.map(p=>p.id)||[]),identity=research?.identity;
 if(research?.candidateId!==c.id||identity?.status!=='matched'||!Array.isArray(identity.matchedPaperIds)||!identity.matchedPaperIds.some(id=>ids.has(id)))return null;
 const sources=new Map((Array.isArray(research.sources)?research.sources:[]).filter(source=>source?.id&&studentSourceUrl(source.url)&&typeof source.evidenceExcerpt==='string'&&source.evidenceExcerpt.trim()).map(source=>[source.id,source]));
 const cited=refs=>Array.isArray(refs)&&refs.length>0&&refs.every(ref=>sources.has(ref)),field=research.academic?.currentStatus;
 if(field?.basis!=='source_stated'||!APP_ACADEMIC_STATUSES.has(field.value)||!cited(field.sourceIds)||!cited(identity.sourceIds))return null;
 return {value:field.value,level,field,sources:[...new Map([...identity.sourceIds,...field.sourceIds].map(id=>{const source=sources.get(id);return [source.url,source]})).values()]};
}
function studentStatusProof(c,research,level='proposed'){const proof=academicStatusProof(c,research,level);return proof&&APP_STUDENT_STATUSES.has(proof.value)?proof:null}
