 if(c.academicProfile?.fields?.currentStatus){const profile=c.academicProfile,research=c.academicResearch,sameIdentity=research?.candidateId===c.id&&JSON.stringify(profile.identity)===JSON.stringify(research.identity);return academicStatusProof(c,{candidateId:c.id,identity:profile.identity,academic:profile.fields,sources:[...(profile.sources||[]),...(sameIdentity?research.sources||[]:[])]},'reviewed')}
 return academicStatusProof(c,c.academicResearch);
