function studentLeadEvidence(c){const proof=academicStatusEvidence(c);return proof&&APP_STUDENT_STATUSES.has(proof.value)?proof:null}
function appProposedCurrentProgram(c){return academicStatusProof(c,c.academicResearch)&&typeof currentProgramFacts==='function'?currentProgramFacts(c):{category:'unknown',currentDegree:null,programStartYear:null,sourceIds:[],sources:[]}}
function appDisplayProgram(c){const reviewed=appCurrentProgram(c);if(c.evidence||reviewed.category!=='unknown'||c.academicProfile?.fields?.programStartYear)return {...reviewed,reviewState:c.evidence?'recruiter_supplied':'reviewed'};const proposed=appProposedCurrentProgram(c);return proposed.category!=='unknown'||proposed.currentDegree?{...proposed,reviewState:'unreviewed'}:{...reviewed,reviewState:'unknown'}}
function appProgramText(c){const p=appDisplayProgram(c);return p.programStartYear!=null?String(p.programStartYear)+(p.reviewState==='unreviewed'?' · unreviewed':''):p.category==='not_currently_studying'?'No current student program established':'Unknown'}
