function academicStatusHtml(c){const proof=academicStatusEvidence(c),value=proof?.value||c.status||'Unknown',note=proof?(proof.level==='reviewed'?'Reviewed cited status':proof.level==='recruiter_supplied'?'Recruiter-supplied · review required':'Cited proposal · unreviewed'):value==='Unknown'?academicUnknownReason(c):'';return `<span class="status">${esc(value)}</span>${note?`<div class="subtext" style="margin-top:5px">${esc(note)}</div>`:''}`}
